create function public.ft_test(ok boolean,label text) returns void language plpgsql as $$begin if not ok then raise exception 'FAILED: %',label;end if;end$$;
select public.ft_test((select count(*)=5 from pg_class where relname in ('ft_jobs','ft_rates','ft_cache','ft_leads','ft_events') and relrowsecurity),'RLS enabled on every new table');
select public.ft_test(not has_table_privilege('anon','public.ft_leads','SELECT'),'No anonymous lead read');
select public.ft_test(not has_function_privilege('authenticated','public.ft_lead(uuid,text,boolean)','EXECUTE'),'No browser write RPC');
select public.ft_admit('fictional-ip','shred',3,100);
select public.ft_admit('fictional-ip','shred',3,100);
select public.ft_admit('fictional-ip','shred',3,100);
do $$begin begin perform public.ft_admit('fictional-ip','shred',3,100);raise exception 'Rate limit failed';exception when raise_exception then if SQLERRM not like 'Free tool limit%' then raise;end if;end;end$$;
select public.ft_test((select n=3 from public.ft_rates where kind='shred' and key='fictional-ip'),'Fourth request did not increment quota');
insert into public.ft_jobs(id,ip_hash,documents,chunks,title,status) values('11111111-1111-4111-8111-111111111111','fictional-job','[]','[]','Fictional test','Completed');
select public.ft_lead('11111111-1111-4111-8111-111111111111','qa@example.invalid',false);
select public.ft_lead('11111111-1111-4111-8111-111111111111','qa@example.invalid',false);
select public.ft_test((select count(*)=1 from public.ft_leads),'Lead retry is idempotent');
do $$begin begin perform public.ft_lead('11111111-1111-4111-8111-111111111111','other@example.invalid',false);raise exception 'Recipient changed';exception when sqlstate 'PT409' then null;end;end$$;
select public.ft_cache_put('fixture','{"value":1}');select public.ft_cache_put('fixture','{"value":2}');
select public.ft_test((select count(*)=1 from public.ft_cache where key='fixture' and body->>'value'='2'),'Expired cache can be refreshed without duplicate conflict');
insert into public.ft_jobs(id,ip_hash,documents,chunks,title)values('22222222-2222-4222-8222-222222222222','fixture','[]','[]','Fictional processing');
select public.ft_test(public.ft_claim('22222222-2222-4222-8222-222222222222') is not null,'First worker claims job');
select public.ft_test(public.ft_claim('22222222-2222-4222-8222-222222222222') is null,'Concurrent worker excluded');
update public.ft_jobs set expires_at=now()-interval '1 hour';select public.ft_cleanup();
select public.ft_test((select count(*)=0 from public.ft_jobs),'Temporary sources removed after expiry');
select public.ft_test((select count(*)=1 from public.ft_leads),'Lead metadata retention independent of source expiry');
select 'Free tool SQL checks passed' as result;
